mapper.select:
SELECT so.id, so.code, so.third_code as thirdCode, so.so_id AS soId, so.so_code AS soCode, so.source_code AS sourceCode, so.source_type AS sourceType, so.source_id AS sourceId, so.order_type AS orderType, so.approve_status AS approveStatus, so.warehouse_org_name AS warehouseOrgName, so.carrier_id AS carrierId, so.invalid_status AS invalidStatus, so.plan_delivery_date AS planDeliveryDate, so.actual_delivery_date AS actualDeliveryDate, so.pack_date AS packDate, so.warehouse_id AS warehouseId, so.warehouse_name AS warehouseName, so.approve_user_name AS approveUserName, so.create_user_name AS createUserName, so.create_time AS createTime, so.seller_id AS sellerId, so.seller_name AS sellerName, so.customer_id AS customerId, so.bill_date AS billDate, so.customer_order_no AS customerOrderNo, so.sales_org_id AS salesOrgId, so.sales_org_name AS salesOrgName, so.customer_name AS customerName, so.country AS countryId, so.track_no AS trackNos, sod.id as detailId, so.sales_dept_id AS salesDeptId, sod.id as detailId, sod.sku_id AS skuId, sod.sku_no AS skuNo, sod.plan_qty AS planQty, sod.actual_qty AS actualQty, sod.price, sod.tax_rate as taxRate, sod.amount, sod.currency, sod.currency_symbol as currencySymbol, sod.all_amount_local_currency as allAmountLocalCurrency, sod.exchange_rate as exchangeRate, sod.so_detail_id as soDetailId, sod.source_detail_id AS sourceDetailId, sod.warehouse_location AS warehouseLocation, so.packing_status, so.logistics_channel_id, so.logistics_channel_name FROM so_outstock so INNER JOIN so_outstock_detail sod ON so.id=sod.main_id AND sod.is_deleted=FALSE WHERE ${params.sqlMap.default} and so.is_deleted=FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sod.id DESC

SELECT so.id, so.code, so.third_code as thirdCode, so.so_id AS soId, so.so_code AS soCode, so.source_type AS sourceType, so.order_type AS orderType, so.source_id AS sourceId, so.source_code AS sourceCode, so.approve_status AS approveStatus, so.warehouse_org_name AS warehouseOrgName, so.carrier_id AS carrierId, so.invalid_status AS invalidStatus, so.plan_delivery_date AS planDeliveryDate, so.actual_delivery_date AS actualDeliveryDate, so.pack_date AS packDate, so.warehouse_id AS warehouseId, so.warehouse_name AS warehouseName, so.approve_user_name AS approveUserName, so.create_user_name AS createUserName, so.create_time AS createTime, so.track_no AS trackNos, so.seller_id AS sellerId, so.seller_name AS sellerName, so.customer_id AS customerId, so.bill_date AS billDate, so.customer_order_no AS customerOrderNo, so.sales_dept_id AS salesDeptId, so.sales_org_id AS salesOrgId, so.sales_org_name AS salesOrgName, so.customer_name AS customerName, so.country AS countryId, sod.id as detailId, sod.sku_id AS skuId, sod.sku_no AS skuNo, sod.plan_qty AS planQty, sod.actual_qty AS actualQty, sod.price, sod.tax_rate as taxRate, sod.amount, sod.currency, sod.currency_symbol as currencySymbol, sod.all_amount_local_currency as allAmountLocalCurrency, sod.exchange_rate as exchangeRate, sod.so_detail_id as soDetailId, sod.source_detail_id AS sourceDetailId, sod.warehouse_location AS warehouseLocation FROM so_outstock so INNER JOIN so_outstock_detail sod ON so.id=sod.main_id AND sod.is_deleted=FALSE WHERE ${params.sqlMap.default} and so.is_deleted=FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sod.id DESC

SELECT so.warehouse_id, so.id AS sourceId, so.code AS sourceCode, sod.id AS sourceDetailId, sod.sku_id,sod.sku_no, sod.warehouse_location, sod.virtual_warehouse_id, sod.actual_qty AS qty, so.bill_date FROM so_outstock so INNER JOIN so_outstock_detail sod ON sod.main_id=so.id AND sod.is_deleted=FALSE WHERE so.is_deleted=FALSE
AND so.id IN
#{id}

SELECT approve_status, invalid_status, count(*) FROM so_outstock WHERE is_deleted=FALSE
${permissionSql}
GROUP BY approve_status,invalid_status

SELECT so.id, so.code, so.source_type, so.seller_name, so.warehouse_name, so.approve_status, so.create_time FROM so_outstock so WHERE so.is_deleted = false AND so.invalid_status = false AND so.source_type NOT IN ('SAL_OUTSTOCK')
and so.approve_status in
#{item}
AND so.actual_delivery_date >= #{params.actualDeliveryDateList[0]} and (#{params.actualDeliveryDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > so.actual_delivery_date
${params.permissionSql}
${item.field} ${item.sort}
ORDER BY so.id desc

select count(distinct so.id) FROM so_outstock_detail sod INNER JOIN so_outstock so ON sod.main_id = so.id AND sod.is_deleted = FALSE WHERE so.is_deleted = FALSE AND so.source_type NOT IN ('SAL_OUTSTOCK')
and so.approve_status in
#{item}
AND so.bill_date >= #{params.billDateList[0]} and (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > so.bill_date
and so.invalid_status = #{params.invalidStatus}
${params.permissionSql}

select count(distinct so.id) FROM so_outstock_detail sod INNER JOIN so_outstock so ON sod.main_id = so.id AND sod.is_deleted = FALSE WHERE so.is_deleted = FALSE AND so.source_type NOT IN ('SAL_OUTSTOCK')
and so.approve_status in
#{item}
AND so.bill_date >= #{params.billDateList[0]} and (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > so.bill_date
and so.invalid_status = #{params.invalidStatus}
${params.permissionSql}

SELECT so.id, wc.box_no as boxNo, concat(box_length, '*', wcs.box_width, '*', wcs.box_height) AS boxSize, box_length*box_width*box_height as multiplySize, wcs.package_weight as packageWeight, (select string_agg(concat(wcd.sku_no,'*',wcd.pack_qty), ',') from wms_carton_detail wcd where wcd.is_deleted = false and wcd.main_id = wc.id) as boxDesc, (select string_agg(wcd.sku_no , ',') from wms_carton_detail wcd where wcd.is_deleted = false and wcd.main_id = wc.id) as sku FROM so_outstock so inner join so_delivery_notice sdn on sdn.id = so.source_id and sdn.is_deleted = false inner join packing_task pt on pt.source_id = sdn.id and pt.is_deleted = false INNER JOIN wms_carton wc ON wc.packing_task_id = pt.id AND wc.is_deleted = FALSE INNER JOIN wms_carton_spec wcs ON wc.spec_id = wcs.id AND wcs.is_deleted = FALSE WHERE so.is_deleted = FALSE AND so.id in
#{id}
ORDER BY CAST(wc.box_no AS INTEGER)

SELECT so.id, so.packing_status, so.code, fmcb.box_no, concat(box_length, '*', fmc.box_width, '*', fmc.box_height) AS boxSize, fmc.package_weight, fmcb.box_desc FROM so_outstock so LEFT JOIN wms_carton_spec fmc ON fmc.source_id = so.id AND fmc.is_deleted = FALSE LEFT JOIN wms_carton fmcb ON fmc.id = fmcb.carton_id AND fmcb.is_deleted = FALSE WHERE ${params.sqlMap.default} AND so.is_deleted = FALSE
${params.permissionSql}
ORDER BY so.code, CAST(fmcb.box_no AS INTEGER)

SELECT so.id as sourceId, so.code as sourceCode, so.country, so.order_type as businessType from so_outstock so inner join so_delivery_notice sdn on sdn.id = so.source_id and sdn.is_deleted = false inner join packing_task pt on pt.source_id = sdn.id and pt.is_deleted = false where so.is_deleted = false and so.country != 'CN' and so.order_type = 'B2B'
AND (pt.packing_status = #{params.packingStatus} or so.approve_status ='approve')
AND so.declare_status = #{params.declareStatus}
AND so.id IN
#{id}

SELECT  EXTRACT(year FROM approve_time),  EXTRACT(month FROM approve_time) as month,
count(1)
from so_outstock so
where is_deleted = false
  and so.declare_status != 'none'

    and  order_type = #{orderType}


    and  approve_status = #{status}


    and approve_time >= #{beginDate}


    and approve_time <=  #{endDate}



    ${permissionSql}

group by EXTRACT(month FROM approve_time), EXTRACT(year FROM approve_time)
order by  EXTRACT(year FROM approve_time), EXTRACT(month FROM approve_time)

select sod.sku_id,sod.sku_no,sod.actual_qty from so_outstock_detail as sod inner join public.so_outstock so on so.id = sod.main_id where so.approve_status = 'approve'
AND sod.id IN
#{id}

